/// <summary>Editors can create tickets; viewers cannot, as editor.</summary>
[TestFixture]
[Category("create-ticket")]
[Category("editor")]
public class CreateTicketEditorTests : PageTest
{
    public override BrowserNewContextOptions ContextOptions() => new()
    {
        BaseURL = Environment.GetEnvironmentVariable("BASE_URL") ?? "http://127.0.0.1:5173",
        // Signed-in session for editor; see README.md.
        StorageStatePath = Environment.GetEnvironmentVariable("TESSA_AUTH_EDITOR") ?? ".auth/editor.json",
    };

    /// <summary>Proves an editor can create a ticket and lands on its detail page.</summary>
    [Test]
    [Description("Editor creates a high-priority ticket")]
    [Property("SeedProfile", "default")]
    [Category("happy-path")]
    public async Task EditorCreatesTicket()
    {
        await Page.GotoAsync("/tickets");
        // 1. Click New ticket
        await Page.GetByTestId("create-ticket").ClickAsync();
        // 2. Enter a title
        await Page.GetByLabel("Title").FillAsync("Export button is misaligned");
        // 3. Choose high priority
        await Page.GetByTestId("ticket-priority").SelectOptionAsync("high");
        // 4. Submit the form
        await Page.GetByRole(AriaRole.Button, new() { Name = "Create ticket" }).ClickAsync();
        // 5. The ticket detail page opens
        await Expect(Page).ToHaveURLAsync(new Regex("^[a-z][a-z0-9+.-]*://[^/]+/tickets/[0-9]+$"));
        // 6. Priority shows high
        await Expect(Page.GetByTestId("ticket-priority-value")).ToHaveTextAsync("high");
    }
}

