    /// <summary>Proves the create permission is enforced in navigation and on the server.</summary>
    [Test]
    [Description("Viewer cannot open the new ticket form")]
    [Property("SeedProfile", "default")]
    public async Task ViewerCannotCreate()
    {
        await Page.GotoAsync("/tickets");
        // 1. No New ticket link in the navigation
        await Expect(Page.GetByTestId("nav-new-ticket")).ToHaveCountAsync(0);
        // 2. Go to the form directly
        await Page.GotoAsync("/tickets/new");
        // 3. A permission error is shown
        await Expect(Page.GetByRole(AriaRole.Alert)).ToContainTextAsync("permission");
